-- =====================================================================
--  IMPORTACIÓN DE LAS 500 DENUNCIAS DEL EXCEL (versión PostgreSQL)
--  Equivale a database/03_importar_excel_500_denuncias.sql de SQL Server.
--  La ejecuta la clase ImportacionExcel al arrancar, UNA sola vez
--  (solo si todavía no hay denuncias DEN-2026-...).
-- =====================================================================
DROP TABLE IF EXISTS imp_funcionario;
DROP TABLE IF EXISTS imp_excel;
CREATE TABLE imp_funcionario (
    codigo    VARCHAR(20) NOT NULL PRIMARY KEY,
    rango     VARCHAR(60) NOT NULL,
    nombres   VARCHAR(80) NOT NULL,
    apellidos VARCHAR(80) NOT NULL,
    dni       VARCHAR(8)  NOT NULL
) ;
CREATE TABLE imp_excel (
    codigo               VARCHAR(20)  NOT NULL PRIMARY KEY,
    tipo_delito          VARCHAR(60)  NOT NULL,
    despacho_fiscal      VARCHAR(150) NOT NULL,
    fiscal_responsable   VARCHAR(120) NOT NULL,
    codigo_funcionario   VARCHAR(20)  NOT NULL,
    nombres              VARCHAR(80)  NOT NULL,
    apellidos            VARCHAR(80)  NOT NULL,
    dni                  VARCHAR(8)   NOT NULL,
    correo               VARCHAR(120) NOT NULL,
    telefono             VARCHAR(15)  NOT NULL,
    fecha_registro       TIMESTAMP  NOT NULL,
    ultima_actualizacion TIMESTAMP  NOT NULL,
    lugar_hechos         VARCHAR(200) NOT NULL,
    estado_policial      VARCHAR(30)  NOT NULL,
    estado_fiscal        VARCHAR(30)  NOT NULL,
    carpeta_fiscal       VARCHAR(20)  NOT NULL
) ;


-- Funcionarios policiales: reciben la misma contraseña (ya cifrada) del usuario PNP-2045
SELECT f.codigo, (SELECT p.password_hash FROM (SELECT password_hash FROM usuario WHERE codigo = 'PNP-2045') p),
       f.nombres, f.apellidos, f.dni, 'PNP', 'POLICIA', f.rango, 'Policía Nacional del Perú', TRUE
FROM imp_funcionario f
WHERE NOT EXISTS (SELECT 1 FROM usuario u WHERE u.codigo = f.codigo);

-- Módulos habilitados para esos funcionarios (los seis del sistema)
SELECT u.id_usuario, m.modulo
FROM usuario u
JOIN imp_funcionario f ON f.codigo = u.codigo
CROSS JOIN (SELECT 'denuncias' AS modulo UNION ALL SELECT 'tracking' UNION ALL SELECT 'documents'
            UNION ALL SELECT 'reports' UNION ALL SELECT 'chat' UNION ALL SELECT 'schedule') m
WHERE NOT EXISTS (SELECT 1 FROM usuario_permiso p WHERE p.id_usuario = u.id_usuario AND p.modulo = m.modulo);

-- Ciudadanos (el PIN lo asigna el portal ciudadano al arrancar)
SELECT e.nombres, e.apellidos, e.dni, e.correo, e.telefono
FROM imp_excel e
WHERE NOT EXISTS (SELECT 1 FROM ciudadano c WHERE c.dni = e.dni);

-- Denuncias, enlazadas con su ciudadano (por DNI) y su funcionario responsable (por código)
                      estado_policial, estado_fiscal, carpeta_fiscal, despacho_fiscal, fiscal_responsable, id_usuario_responsable)
SELECT e.codigo, c.id_ciudadano, e.tipo_delito,
       CONCAT('Denuncia por ', LOWER(e.tipo_delito), ' presentada por ', e.nombres, ' ', e.apellidos,
              '. Los hechos ocurrieron en ', e.lugar_hechos, '.'),
       e.lugar_hechos, e.fecha_registro, e.ultima_actualizacion,
       e.estado_policial, e.estado_fiscal, e.carpeta_fiscal, e.despacho_fiscal, e.fiscal_responsable, u.id_usuario
FROM imp_excel e
JOIN ciudadano c ON c.dni = e.dni
JOIN usuario u ON u.codigo = e.codigo_funcionario
WHERE NOT EXISTS (SELECT 1 FROM denuncia d WHERE d.codigo = e.codigo);

-- Historial: la última actualización de cada denuncia
SELECT d.id_denuncia, e.codigo_funcionario, 'POLICIA', e.estado_policial, NULL, e.ultima_actualizacion
FROM imp_excel e
JOIN denuncia d ON d.codigo = e.codigo
WHERE e.ultima_actualizacion > e.fecha_registro
  AND NOT EXISTS (SELECT 1 FROM seguimiento_denuncia s WHERE s.id_denuncia = d.id_denuncia);

DROP TABLE IF EXISTS imp_funcionario;
DROP TABLE IF EXISTS imp_excel;

